[{"order":1,"type":"heading","text":"Handling Alerts, Prompts, and Confirmation Popups in Selenium"},{"order":2,"type":"paragraph","text":"When automating web applications, you will often encounter JavaScript popup boxes. These popups are not standard HTML elements, meaning you cannot locate them using traditional Selenium locator strategies like id, name, or xpath. Instead, Selenium provides the TargetLocator interface, accessed via driver.switchTo().alert(), to interact with these browser-level dialogs."},{"order":3,"type":"subheading","text":"Types of JavaScript Popups"},{"order":4,"type":"bullet_point","text":"Alert Box: Displays a warning or a simple message with a single "OK" button."},{"order":5,"type":"bullet_point","text":"Confirmation Box: Asks the user for permission to perform an action, providing both "OK" and "Cancel" buttons."},{"order":6,"type":"bullet_point","text":"Prompt Box: Requests user input via a text field, along with "OK" and "Cancel" buttons."},{"order":7,"type":"subheading","text":"Step-by-Step Implementation"},{"order":8,"type":"paragraph","text":"Below is a complete Java Selenium example demonstrating how to switch to and interact with all three types of JavaScript popups."},{"order":9,"type":"code","text":"import org.openqa.selenium.Alert;
import org.openqa.selenium.By;
import org.openqa.selenium.WebDriver;
import org.openqa.selenium.chrome.ChromeDriver;

public class AlertTutorial {
    public static void main(String[] args) throws InterruptedException {
        WebDriver driver = new ChromeDriver();
        driver.get("https://example.com/alerts");

        // 1. Handling Simple Alert
        driver.findElement(By.id("alertButton")).click();
        Alert simpleAlert = driver.switchTo().alert();
        System.out.println("Alert text: " + simpleAlert.getText());
        simpleAlert.accept();

        // 2. Handling Confirmation Popup
        driver.findElement(By.id("confirmButton")).click();
        Alert confirmAlert = driver.switchTo().alert();
        System.out.println("Confirmation text: " + confirmAlert.getText());
        confirmAlert.dismiss(); // Clicks 'Cancel'

        // 3. Handling Prompt Popup
        driver.findElement(By.id("promptButton")).click();
        Alert promptAlert = driver.switchTo().alert();
        promptAlert.sendKeys("Selenium Automation");
        promptAlert.accept();

        driver.quit();
    }
}"},{"order":10,"type":"subheading","text":"Key Methods of the Alert Interface"},{"order":11,"type":"bullet_point","text":"accept(): Clicks the "OK" button on the alert."},{"order":12,"type":"bullet_point","text":"dismiss(): Clicks the "Cancel" button on the alert."},{"order":13,"type":"bullet_point","text":"getText(): Retrieves the message displayed inside the alert box."},{"order":14,"type":"bullet_point","text":"sendKeys(String text): Enters text into the prompt input box."},{"order":15,"type":"subheading","text":"Best Practices and Troubleshooting"},{"order":16,"type":"paragraph","text":"Always ensure the alert is fully loaded before attempting to switch to it, or you will encounter a NoAlertPresentException. Implementing explicit waits using ExpectedConditions.alertIsPresent() is highly recommended in production test suites to stabilize execution."}]
